create table if not exists public.app_users(id uuid primary key default gen_random_uuid(),google_sub text not null unique,email text not null unique,full_name text,avatar_url text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),last_login_at timestamptz);create index if not exists app_users_google_sub_idx on public.app_users(google_sub);alter table public.app_users enable row level security;do $$declare c record;begin for c in select constraint_name from information_schema.table_constraints where table_schema='public' and table_name='commute_routes' and constraint_type='FOREIGN KEY' and constraint_name ilike '%user%' loop execute format('alter table public.commute_routes drop constraint if exists %I',c.constraint_name);end loop;end$$;alter table public.commute_routes add constraint commute_routes_app_user_fk foreign key(user_id) references public.app_users(id) on delete cascade;